-    all: "All",
-    ollama: "Ollama",
-    omni: "Omni",
-    llamacpp: "llama.cpp",
-    google: "Google",
-    grok: "Grok",
-    openrouter: "OpenRouter",
-    together: "Together AI",
-    cerebras: "Cerebras",
-    openai: "OpenAI",
-    anthropic: "Anthropic",
-    configured: "Configured",
-    unknown: "Other",
