-    tab.dataset.provider = provider;
-    tab.addEventListener("click", () => {
-      state.modelProvider = provider;
-      document.querySelectorAll(".model-provider-tab").forEach((x) => x.classList.toggle("selected", x === tab));
-      renderModelGroups();
-    });
-    wrap.appendChild(tab);
-  });
-}
-
